//! Concrete implementation of the repository

use std::str::FromStr;

use crate::{
    domain::{
        models::{
            entity_search::EntitySearchRequest,
            funder::{Funder, FunderId, FunderKind},
            search_similarity::SearchSimilarity,
        },
        repositories::funder_repository::{FunderRepo, FunderRepoError},
    },
    outbound::postgres::ExposedDatabase,
};

impl FunderRepo for ExposedDatabase {
    async fn get_funders_by_text_search_score(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<(Funder, SearchSimilarity)>, FunderRepoError> {
        sqlx::query!(
            "
            SELECT
                f.id,
                f.funder_name as name,
                f.funder_kind as kind,
                f.company_number,
                GREATEST(
                    word_similarity($1, f.funder_name),
                    COALESCE((
                        SELECT MAX(word_similarity($1, a.funder_alias))
                        FROM exposed.funder_aliases a
                        WHERE a.funder_id = f.id
                    ), 0)
                ) as similarity_score,
                row_number() OVER (ORDER BY GREATEST(
                    word_similarity($1, f.funder_name),
                    COALESCE((
                        SELECT MAX(word_similarity($1, a.funder_alias))
                        FROM exposed.funder_aliases a
                        WHERE a.funder_id = f.id
                    ), 0)
                ) DESC) as rank
            FROM exposed.funders f
            WHERE GREATEST(
                word_similarity($1, f.funder_name),
                COALESCE((
                    SELECT MAX(word_similarity($1, a.funder_alias))
                    FROM exposed.funder_aliases a
                    WHERE a.funder_id = f.id
                ), 0)
            ) >= $2
            ORDER BY similarity_score DESC
            ",
            req.term(),
            req.strictness(),
        )
        .fetch_all(self.pool())
        .await
        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?
        .into_iter()
        .take_while(|r| {
            r.rank.unwrap_or_else(|| i64::from(req.max_entries() + 1))
                <= i64::from(req.max_entries())
        })
        .map(|r| {
            let kind = r.kind.map_or(FunderKind::NotSpecified, |ref kind| {
                FunderKind::from_str(kind).unwrap()
            });
            let funder = Funder::new(FunderId::new(r.id), r.name, kind);
            let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
            Ok((funder, score))
        })
        .collect()
    }
}

#[cfg(test)]
mod scoring {
    use sqlx::PgPool;

    use crate::{
        domain::{
            models::entity_search::EntitySearchRequest, repositories::funder_repository::FunderRepo,
        },
        outbound::postgres::ExposedDatabase,
    };

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures(
            "../../../../db/fixtures/add_members.sql",
            "../../../../db/fixtures/add_declarations_and_funding_entries.sql"
        )
    )]
    async fn orders_correctly(pool: PgPool) -> sqlx::Result<()> {
        let db = ExposedDatabase::from(pool);

        let term = EntitySearchRequest::new_with_strictness("McDonald's".into(), 5, 0_f32).unwrap();
        let results = db.get_funders_by_text_search_score(&term).await.unwrap();

        assert_eq!(results.len(), 2);
        assert_eq!(results.first().unwrap().0.name(), "McDonald's");

        Ok(())
    }

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures(
            "../../../../db/fixtures/add_members.sql",
            "../../../../db/fixtures/add_declarations_and_funding_entries.sql"
        )
    )]
    async fn obeys_max_entries(pool: PgPool) -> sqlx::Result<()> {
        let db = ExposedDatabase::from(pool);

        let term = EntitySearchRequest::new_with_strictness("McDonald's".into(), 1, 0_f32).unwrap();
        let results = db.get_funders_by_text_search_score(&term).await.unwrap();

        assert_eq!(results.len(), 1);
        assert_eq!(results.first().unwrap().0.name(), "McDonald's");

        Ok(())
    }
    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures(
            "../../../../db/fixtures/add_members.sql",
            "../../../../db/fixtures/add_declarations_and_funding_entries.sql"
        )
    )]
    async fn filters_similarity(pool: PgPool) -> sqlx::Result<()> {
        let db = ExposedDatabase::from(pool);

        let term =
            EntitySearchRequest::new_with_strictness("Aaron Banks".into(), 5, 1_f32).unwrap();
        let results = db.get_funders_by_text_search_score(&term).await.unwrap();

        assert_eq!(results.len(), 1);
        assert_eq!(results.first().unwrap().0.name(), "Aaron Banks");

        Ok(())
    }
}
//! Funders give financial compensation to [`parliament_members`]

use std::str::FromStr;
use uuid::Uuid;

use strum::{AsRefStr, EnumString};

#[derive(Clone, Debug, PartialEq, Eq)]
/// Funder of MP declarations
pub struct Funder {
    id: FunderId,
    name: String,
    kind: FunderKind,
}

impl Funder {
    #[must_use]
    /// Creates a new instance
    pub const fn new(id: FunderId, name: String, funder_kind: FunderKind) -> Self {
        Self {
            id,
            name,
            kind: funder_kind,
        }
    }

    /// Persistent funder identity.
    #[must_use]
    pub const fn id(&self) -> FunderId {
        self.id
    }

    #[must_use]
    /// Gets funder name
    pub fn name(&self) -> &str {
        &self.name
    }

    #[must_use]
    /// Gets legal person
    pub fn kind(&self) -> &str {
        self.kind.as_ref()
    }
}

#[derive(Clone, Debug, AsRefStr, EnumString, PartialEq, Eq)]
/// All possible funder kinds
#[allow(missing_docs)] // Self explanatory
pub enum FunderKind {
    Company,
    Individual,
    Trust,
    #[strum(serialize = "Trade Union")]
    TradeUnion,
    Other,
    /// We don't know what this is supposed to be
    #[strum(serialize = "Not Specified")]
    NotSpecified,
    #[strum(serialize = "Building society")]
    BuildingSociety,
    #[strum(serialize = "Limited Liability Partnership")]
    LimitedLiabilityPartnership,
    #[strum(serialize = "Unincorporated association")]
    UnincorporatedAssociation,
    #[strum(serialize = "Friendly society")]
    FriendlySociety,
    #[strum(serialize = "Registered Party")]
    RegisteredParty,
}

/// Persistent exact-name funder identity.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FunderId(Uuid);

impl FunderId {
    /// Wraps a database identity.
    #[must_use]
    pub const fn new(id: Uuid) -> Self {
        Self(id)
    }
    /// Database identity.
    #[must_use]
    pub const fn value(self) -> Uuid {
        self.0
    }
}

impl FromStr for FunderId {
    type Err = uuid::Error;
    fn from_str(value: &str) -> Result<Self, Self::Err> {
        value.parse().map(Self)
    }
}
