   623	        digest.update(u64::try_from(name.len()).unwrap_or(u64::MAX).to_be_bytes());
   624	        digest.update(name.as_bytes());
   625	        digest.update(u64::try_from(bytes.len()).unwrap_or(u64::MAX).to_be_bytes());
   626	        digest.update(bytes);
   627	    }
   628	    Ok(format!("{:x}", digest.finalize()))
