    68	            }
    69	            Some(_) => NameStatus::Present,
    70	        };
    71	        let (parenthetical_text, has_unbalanced_parentheses) = parentheses(raw.unwrap_or(""));
    72	        let usable = normalized.filter(|_| name_status == NameStatus::Present);
    73	        let name_accent_folded = usable.as_ref().map(|name| {
    74	            name.nfd()
    75	                .filter(|c| !is_combining_mark(*c))
