   262	fn alias_marker(candidate: &str, top_level_only: bool) -> Option<(usize, usize)> {
   263	    let lower = candidate.to_ascii_lowercase();
   264	    let mut found = None;
   265	    for marker in ["trading as", "t/a"] {
   266	        for (index, _) in lower.match_indices(marker) {
   267	            let boundary = (index == 0 || lower[..index].ends_with([' ', '(', ',']))
   268	                && lower[index + marker.len()..].starts_with(char::is_whitespace);
   269	            let depth = candidate[..index].chars().fold(0_i32, |depth, c| match c {
   270	                '(' => depth + 1,
   271	                ')' => depth - 1,
   272	                _ => depth,
   273	            });
   274	            if boundary
   275	                && (!top_level_only || depth == 0)
   276	                && found.is_none_or(|(previous, _)| index < previous)
   277	            {
   278	                found = Some((index, marker.len()));
   279	            }
   280	        }
   281	    }
   282	    found
   283	}
   284	
   285	fn aliases(raw: &str, parenthetical: &[String]) -> Vec<String> {
   286	    let mut result = Vec::new();
   287	    for (candidate, top_level_only) in parenthetical
   288	        .iter()
   289	        .map(|name| (name.as_str(), false))
   290	        .chain(std::iter::once((raw, true)))
   291	    {
   292	        if let Some((index, length)) = alias_marker(candidate, top_level_only) {
   293	            let alias = candidate[index + length..].trim().to_owned();
   294	            if !alias.is_empty() && !result.contains(&alias) {
   295	                result.push(alias);
   296	            }
   297	        }
   298	    }
   299	    result
   300	}
   301	
   302	fn primary_name(raw: &str) -> String {
   303	    let mut result = String::new();
   304	    let mut depth = 0;
   305	    let mut start = 0;
   306	    let mut keep_from = 0;
   307	    for (index, c) in raw.char_indices() {
   308	        match c {
   309	            '(' => {
   310	                if depth == 0 {
   311	                    start = index;
   312	                }
   313	                depth += 1;
   314	            }
   315	            ')' if depth > 0 => {
   316	                depth -= 1;
   317	                if depth == 0 && alias_marker(&raw[start + 1..index], false).is_some() {
   318	                    result.push_str(&raw[keep_from..start]);
   319	                    result.push(' ');
   320	                    keep_from = index + 1;
   321	                }
   322	            }
   323	            _ => {}
   324	        }
   325	    }
   326	    result.push_str(&raw[keep_from..]);
   327	    if let Some((index, _)) = alias_marker(&result, true) {
   328	        result.truncate(index);
   329	    }
   330	    result.trim().trim_end_matches(',').trim().to_owned()
   331	}
