   611	fn fingerprint_files(
   612	    paths: impl IntoIterator<Item = PathBuf>,
   613	) -> Result<String, EntityIngestionError> {
   614	    let mut paths = paths.into_iter().collect::<Vec<_>>();
   615	    paths.sort();
   616	    let mut digest = Sha256::new();
   617	    for path in paths {
   618	        let name = path
   619	            .file_name()
   620	            .and_then(|name| name.to_str())
   621	            .ok_or_else(|| data_error("artifact filename is not UTF-8"))?;
   622	        let bytes = fs::read(&path).map_err(read_error)?;
   623	        digest.update(u64::try_from(name.len()).unwrap_or(u64::MAX).to_be_bytes());
   624	        digest.update(name.as_bytes());
   625	        digest.update(u64::try_from(bytes.len()).unwrap_or(u64::MAX).to_be_bytes());
   626	        digest.update(bytes);
   627	    }
   628	    Ok(format!("{:x}", digest.finalize()))
   629	}
