    59	impl FunderNameFeatures {
    60	    /// Derives parallel features while retaining the original evidence.
    61	    #[must_use]
    62	    pub fn from_name(raw: Option<&str>) -> Self {
    63	        let normalized = raw.map(normalize);
    64	        let name_status = match normalized.as_deref() {
    65	            None | Some("") => NameStatus::Missing,
    66	            Some("confidential" | "withheld" | "name withheld" | "anonymous" | "not disclosed") => {
    67	                NameStatus::Withheld
    68	            }
    69	            Some(_) => NameStatus::Present,
    70	        };
    71	        let (parenthetical_text, has_unbalanced_parentheses) = parentheses(raw.unwrap_or(""));
    72	        let usable = normalized.filter(|_| name_status == NameStatus::Present);
    73	        let name_accent_folded = usable.as_ref().map(|name| {
    74	            name.nfd()
    75	                .filter(|c| !is_combining_mark(*c))
    76	                .collect::<String>()
    77	        });
    78	        let name_tokens = usable.as_deref().map(tokens);
    79	        let has_conjunction = name_tokens
    80	            .as_deref()
    81	            .is_some_and(|name| name.split_whitespace().any(|word| word == "and"));
    82	        let name_token_key = name_tokens.as_deref().map(|name| {
    83	            let mut words = name.split_whitespace().collect::<Vec<_>>();
    84	            words.sort_unstable();
    85	            words.join(" ")
    86	        });
    87	        let primary_name_normalized = raw
    88	            .filter(|_| name_status == NameStatus::Present)
    89	            .map(|raw| normalize(&primary_name(raw)));
    90	        let organisation_core = primary_name_normalized
    91	            .as_deref()
    92	            .map(|name| organisation_core(&tokens(name)));
    93	        let person_core = name_tokens.as_deref().map(person_core);
    94	        let person_initials = person_core.as_deref().map(|name| initials(name, false));
    95	        let organisation_initials = organisation_core
    96	            .as_deref()
    97	            .map(|name| initials(name, true));
    98	        let (explicit_acronym, acronym_expansion_normalized) = raw
    99	            .and_then(|name| explicit_acronym(name, &parenthetical_text))
   100	            .unzip();
   101	        let explicit_aliases = raw.map_or_else(Vec::new, |name| aliases(name, &parenthetical_text));
   102	        let alias_normalized = explicit_aliases
   103	            .iter()
   104	            .map(|name| normalize(name))
   105	            .collect();
   106	        Self {
   107	            name_raw: raw.map(str::to_owned),
   108	            name_status,
   109	            name_normalized: usable,
   110	            name_accent_folded,
   111	            name_tokens,
   112	            name_token_key,
   113	            primary_name_normalized,
   114	            organisation_core,
   115	            person_core,
   116	            person_initials,
   117	            organisation_initials,
   118	            explicit_acronym,
   119	            acronym_expansion_normalized,
   120	            parenthetical_text,
   121	            explicit_aliases,
   122	            alias_normalized,
   123	            has_conjunction,
   124	            has_unbalanced_parentheses,
   125	        }
   260	}
   261	
   262	fn alias_marker(candidate: &str, top_level_only: bool) -> Option<(usize, usize)> {
   263	    let lower = candidate.to_ascii_lowercase();
   264	    let mut found = None;
   265	    for marker in ["trading as", "t/a"] {
   266	        for (index, _) in lower.match_indices(marker) {
   267	            let boundary = (index == 0 || lower[..index].ends_with([' ', '(', ',']))
   268	                && lower[index + marker.len()..].starts_with(char::is_whitespace);
   269	            let depth = candidate[..index].chars().fold(0_i32, |depth, c| match c {
   270	                '(' => depth + 1,
   271	                ')' => depth - 1,
   272	                _ => depth,
   273	            });
   274	            if boundary
   275	                && (!top_level_only || depth == 0)
   276	                && found.is_none_or(|(previous, _)| index < previous)
   277	            {
   278	                found = Some((index, marker.len()));
   279	            }
   280	        }
   281	    }
   282	    found
   283	}
   284	
   285	fn aliases(raw: &str, parenthetical: &[String]) -> Vec<String> {
   286	    let mut result = Vec::new();
   287	    for (candidate, top_level_only) in parenthetical
   288	        .iter()
   289	        .map(|name| (name.as_str(), false))
   290	        .chain(std::iter::once((raw, true)))
   291	    {
   292	        if let Some((index, length)) = alias_marker(candidate, top_level_only) {
   293	            let alias = candidate[index + length..].trim().to_owned();
   294	            if !alias.is_empty() && !result.contains(&alias) {
   295	                result.push(alias);
   296	            }
   297	        }
   298	    }
   299	    result
   300	}
   301	
   302	fn primary_name(raw: &str) -> String {
   303	    let mut result = String::new();
   304	    let mut depth = 0;
   305	    let mut start = 0;
   306	    let mut keep_from = 0;
   307	    for (index, c) in raw.char_indices() {
   308	        match c {
   309	            '(' => {
   310	                if depth == 0 {
   311	                    start = index;
   312	                }
   313	                depth += 1;
   314	            }
   315	            ')' if depth > 0 => {
   316	                depth -= 1;
   317	                if depth == 0 && alias_marker(&raw[start + 1..index], false).is_some() {
   318	                    result.push_str(&raw[keep_from..start]);
   319	                    result.push(' ');
   320	                    keep_from = index + 1;
   321	                }
   322	            }
   323	            _ => {}
   324	        }
   325	    }
   326	    result.push_str(&raw[keep_from..]);
   327	    if let Some((index, _)) = alias_marker(&result, true) {
   328	        result.truncate(index);
   329	    }
   330	    result.trim().trim_end_matches(',').trim().to_owned()
   331	}
